using System.IO;
using System.Windows;
using System.Windows.Controls;
namespace PhotoTrail.Windows;
public partial class MainWindow {
 TrackWorkspaceSnapshot? trackWorkspace;bool restoringTrackWorkspace;int trackWorkspacePending;readonly SemaphoreSlim trackWorkspaceGate=new(1);
 async Task LoadTrackSnapshotsAsync(){restoringTrackWorkspace=true;try{var cached=TrackSnapshots.Read(TrackSnapshots.DefaultPath);trackWorkspace=TrackWorkspace.Read(TrackWorkspace.DefaultPath);var entries=trackWorkspace.Revision=="missing"?cached.Select(r=>new TrackWorkspaceEntry(r.Path)).ToArray():trackWorkspace.State.Entries;var restored=new List<TrackRow>();foreach(var entry in entries){var record=cached.SingleOrDefault(r=>r.Path.Equals(entry.Path,StringComparison.OrdinalIgnoreCase))??throw new InvalidDataException(L10n.Text("工作区缺少对应的已验证缓存，未以空库覆盖。"));bool unavailable=false;try{await TrackSnapshots.EnsureSourceAsync(record);}catch(Exception e)when(e is IOException or UnauthorizedAccessException){unavailable=true;}restored.Add(new(record){Visible=entry.Visible,SourceUnavailable=unavailable});}tracks.Clear();foreach(var row in restored)tracks.Add(row);TrackList.SelectedItem=tracks.FirstOrDefault(r=>r.Path==trackWorkspace.State.Selected)??tracks.FirstOrDefault();RefreshTrackWorkspaceStatus();}catch(Exception){trackWorkspace=null;TrackWorkspaceStatus.Text=L10n.Message(L10n.Text("轨迹缓存/工作区不可读取；原记录不覆盖，当前会话仍可安全查看新导入来源。"));}finally{restoringTrackWorkspace=false;}}
 void RefreshTrackWorkspaceStatus(){TrackDisplayRows.Items.Refresh();TrackWorkspaceStatus.Text=L10n.Message(L10n.Format("当前{0}条，显示{1}条；可匹配{2}条；失联/变化{3}条仅预览/另存缓存。显隐不改变匹配集合。",tracks.Count,tracks.Count(r=>r.Visible),tracks.Count(r=>!r.SourceUnavailable&&r.Data.Segments.Any(s=>s.Any(p=>p.Time is not null))),tracks.Count(r=>r.SourceUnavailable)));RefreshBatchTrackControls();}
 async Task SaveCurrentTrackWorkspaceAsync(){if(restoringTrackWorkspace)return;trackWorkspacePending++;try{await trackWorkspaceGate.WaitAsync();try{if(trackWorkspace is null)throw new IOException(L10n.Text("原工作区不可读取，未覆盖。"));var cache=TrackSnapshots.Read(TrackSnapshots.DefaultPath);if(tracks.Any(row=>!cache.Any(r=>r.Path==row.Path&&r.SourceHash==row.Snapshot.SourceHash&&TrackAdjustment.Equal(r.Data,row.Data))))throw new IOException(L10n.Text("当前轨迹尚无已验证缓存，不能声称可恢复。"));var state=new TrackWorkspaceState(1,tracks.Select(r=>new TrackWorkspaceEntry(r.Path,r.Visible)).ToArray(),(TrackList.SelectedItem as TrackRow)?.Path);trackWorkspace=await TrackWorkspace.SaveAsync(TrackWorkspace.DefaultPath,trackWorkspace,state);}finally{trackWorkspaceGate.Release();}}catch(Exception){TrackWorkspaceStatus.Text=L10n.Message(L10n.Text("当前轨迹/显隐保持，但工作区未保存（损坏、缓存缺失或多实例冲突）；原文件保留，不能声称重启已恢复。"));}finally{trackWorkspacePending--;}}
 private async void TrackVisibilityChanged(object sender,RoutedEventArgs e){if(sender is not CheckBox{DataContext:TrackRow row} box||row.Visible==(box.IsChecked==true)||busy||restoringTrackWorkspace)return;row.Visible=box.IsChecked==true;RefreshTrackWorkspaceStatus();await PostTrackAsync(false);await SaveCurrentTrackWorkspaceAsync();}
 private async void ReloadTrackWorkspace(object s,RoutedEventArgs e){if(busy)return;BeginOperation();try{InvalidateTrackAdjustment();ClearMatchMarker();await LoadTrackSnapshotsAsync();await PostTrackAsync(false);}finally{EndOperation();}}
 private async void SaveTrackWorkspace(object s,RoutedEventArgs e){if(busy)return;await SaveCurrentTrackWorkspaceAsync();}
 private async void RefreshCurrentTrack(object s,RoutedEventArgs e){if(!busy&&TrackList.SelectedItem is TrackRow row)await ImportTracksAsync([row.Path],true);}
}
